export default function Button({
  children,
  variant = "solid",
  size = "md",
  loading = false,
  ...props
}: ButtonProps) {
  const shape = useShape();
  const classes = merge(BASE, SIZES[size], RADIUS.control[shape]);
  return (
    <BaseButton className={classes} disabled={loading} {...props}>
      {loading ? <Spinner /> : children}
    </BaseButton>
  );
}
